const chk = (id, label, on) => `<label style="display:flex;gap:8px;align-items:center;margin:6px 0;color:inherit;"><input type="checkbox" id="${id}"${on ? ' checked' : ''} style="width:auto;"> ${esc(label)}</label>`;
