  <div class="card"><h2>Who may sell</h2>${chk('stLicReq', 'Agents must hold a licence number before sending an application', c.licensing.required)}${chk('stLicBlock', 'Block agents whose licence has expired', c.licensing.blockExpired)}${chk('stQuiz', 'Agents must pass the knowledge quiz', c.licensing.quizRequired)}<div class="row">${num('stPass', 'Quiz pass mark (%)', c.licensing.passMark, 50, 100)}${num('stQDays', 'Quiz valid for (days)', c.licensing.quizValidDays, 30, 1095)}${num('stWarn', 'Warn about expiry (days before)', c.licensing.warnDays, 1, 180)}</div></div>
